BEGIN;
CREATE TABLE IF NOT EXISTS shared_capacity_resources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID,resource_type VARCHAR(40) NOT NULL,name TEXT NOT NULL,location JSONB,cold_chain BOOLEAN NOT NULL DEFAULT FALSE,unit VARCHAR(30) NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',active BOOLEAN NOT NULL DEFAULT TRUE,created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shared_capacity_slots(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),resource_id UUID NOT NULL REFERENCES shared_capacity_resources(id) ON DELETE CASCADE,start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ NOT NULL,total_capacity NUMERIC(16,4) NOT NULL CHECK(total_capacity>0),available_capacity NUMERIC(16,4) NOT NULL CHECK(available_capacity>=0 AND available_capacity<=total_capacity),unit VARCHAR(30) NOT NULL,price_per_unit NUMERIC(16,4) NOT NULL DEFAULT 0 CHECK(price_per_unit>=0),created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS shared_capacity_reservations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slot_id UUID NOT NULL REFERENCES shared_capacity_slots(id),tenant_id UUID,requester_id UUID NOT NULL REFERENCES users(id),quantity NUMERIC(16,4) NOT NULL CHECK(quantity>0),status VARCHAR(20) NOT NULL CHECK(status IN('confirmed','held','waitlisted','fulfilled','cancelled','expired')),hold_expires_at TIMESTAMPTZ,idempotency_key VARCHAR(100) NOT NULL,purpose TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(requester_id,idempotency_key));
CREATE TABLE IF NOT EXISTS shared_capacity_events(id BIGSERIAL PRIMARY KEY,reservation_id UUID NOT NULL REFERENCES shared_capacity_reservations(id) ON DELETE CASCADE,event_type VARCHAR(30) NOT NULL,actor_id UUID REFERENCES users(id) ON DELETE SET NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_capacity_slots_available ON shared_capacity_slots(resource_id,start_at,end_at) WHERE available_capacity>0;
CREATE INDEX IF NOT EXISTS idx_capacity_waitlist ON shared_capacity_reservations(slot_id,created_at) WHERE status='waitlisted';
COMMIT;
